/** 高级折叠（连接三键 + 历史两键；字段表驱动，加字段只改表不改 JSX）。 */
function AdvancedSection(props: {
  readonly open: boolean;
  readonly onToggle: (open: boolean) => void;
  readonly fields: ReadonlyArray<readonly [string, string, (v: string) => void, string]>;
